SELECT CASE tipo_acao WHEN 'resgate_escravidao' THEN 'Resgate de trabalho escravo'             WHEN 'embargo_interdicao' THEN 'Embargo ou interdição'             WHEN 'autuacao' THEN 'Autuação ou multa'             WHEN 'acidente' THEN 'Acidente ou óbito'             WHEN 'fiscalizacao' THEN 'Fiscalização ou operação'             ELSE 'Segurança e saúde em geral' END AS tipo_acao,        data_publicacao, titulo, ufs, cita_obito FROM {{ source('bronze', 'mte_noticias') }}
